def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split at the uniform divider.
    sep_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_row is not None:
        parts = [grid[:sep_row], grid[sep_row + 1:]]
    else:
        sep_col = next(c for c in range(w)
                       if len({grid[r][c] for r in range(h)}) == 1)
        parts = [
            [row[:sep_col] for row in grid],
            [row[sep_col + 1:] for row in grid]
        ]

    def minority(part):
        counts = {}
        total = 0
        for row in part:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
                total += 1
        rare = min(counts, key=counts.get)
        common = max(counts, key=counts.get)
        return counts[rare] / total, rare, common

    _, rare, common = min((minority(p) for p in parts), key=lambda x: x[0])
    chosen = next(p for p in parts if rare in {x for row in p for x in row}
                  and common in {x for row in p for x in row}
                  and minority(p)[1:] == (rare, common))

    return [[3 if x == rare else common for x in row] for row in chosen]
